+++ b/modular_exponentiation.java
@@ -1,26 +1,23 @@
 class ModularExponentiation {
-    public int powMod(int x, int n, int M) {
-        int res = 1;
+    public int powMod(int base, int exp, int mod) {
+        long result = 1;
+        long b = base % mod;

-        while (n >= 1) {
-
-            if ((n & 1) == 1) {
-                res = (int)((1L * res * x) % M);
-
-                n--;
-             } else {
-
-                x = (int)((1L * x * x) % M);
-                n /= 2;
+        while (exp > 0) {
+            if ((exp & 1) == 1) {
+                result = result * b % mod;
             }
+            b = b * b % mod;
+            exp >>= 1;
         }

-        return res;
+        return (int) result;
     }

     public static void main(String[] args) {
-        int x = 3, n = 2, M = 4;
         ModularExponentiation obj = new ModularExponentiation();
-        System.out.println(obj.powMod(x, n, M));
+        System.out.println(obj.powMod(3, 2, 4));   // 9 % 4 = 1
+        System.out.println(obj.powMod(2, 10, 1000)); // 1024 % 1000 = 24
+        System.out.println(obj.powMod(5, 0, 7));    // 1
     }
 }
